@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Nunito:wght@500;600;700;800;900&display=swap');
:root{--ink:#25433b;--muted:#70867b;--mint:#83c9a7;--cream:#fffdf5;--line:rgba(48,85,70,.12);--shadow:0 12px 40px rgba(49,83,65,.13)}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;font-family:'Nunito',sans-serif;color:var(--ink);background:#b4e8e8}button{font:inherit;color:inherit;border:0;cursor:pointer}#game-shell{position:relative;width:100vw;height:100dvh;overflow:hidden;background:linear-gradient(180deg,#9fe2ed 0%,#d1f1d8 55%,#a5cf8b 100%);isolation:isolate}#game-canvas{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}.topbar{position:absolute;top:0;left:0;right:0;height:76px;padding:0 38px;display:flex;align-items:center;justify-content:space-between;z-index:5;background:linear-gradient(180deg,rgba(251,255,248,.72),rgba(251,255,248,0));pointer-events:none}.topbar>*{pointer-events:auto}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:#264e3e;font-weight:900;letter-spacing:1.6px;font-size:15px}.brand-light{font-weight:600;letter-spacing:1.3px}.brand-mark{width:26px;height:26px;display:grid;grid-template-columns:1fr 1fr;gap:2px;transform:rotate(-8deg)}.brand-mark span{background:#77ba7a;border:1px solid rgba(42,91,63,.18);box-shadow:inset -2px -2px 0 rgba(41,88,52,.13)}.brand-mark span:nth-child(2){background:#b4d681}.brand-mark span:nth-child(3){background:#85c894}.brand-mark span:nth-child(4){background:#e8c978}.world-label{display:flex;align-items:center;gap:9px;color:#52766b;font:500 10px 'DM Mono',monospace;letter-spacing:1.1px}.live-dot{height:7px;width:7px;background:#77c394;border-radius:50%;box-shadow:0 0 0 4px rgba(119,195,148,.16)}.divider{opacity:.45}.icon-button,.rail-button{background:rgba(255,255,255,.55);border:1px solid rgba(255,255,255,.75);box-shadow:0 5px 16px rgba(39,77,58,.08);backdrop-filter:blur(12px);border-radius:12px}.sound-toggle{width:39px;height:39px;font-size:18px;color:#638777}.left-panel{position:absolute;z-index:3;left:6.3%;top:50%;transform:translateY(-46%);width:310px;padding:30px 28px 22px}.glass{background:rgba(255,255,249,.79);border:1px solid rgba(255,255,255,.84);box-shadow:var(--shadow);backdrop-filter:blur(18px);border-radius:18px}.panel-kicker{font:500 9px 'DM Mono',monospace;letter-spacing:1.9px;color:#79a78c;margin-bottom:12px}.left-panel h1,.start-card h2{font-size:35px;line-height:1.08;letter-spacing:-1.6px;margin:0;color:#315b49;font-weight:900}.left-panel h1 em,.start-card h2 em{font-style:normal;color:#82bb8c}.left-panel>p,.start-card>p{font-size:13px;line-height:1.6;color:#788c7e;margin:13px 0 22px}.world-stats{display:flex;gap:18px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:13px 0;margin-bottom:18px}.world-stats>div{display:flex;align-items:center;gap:8px}.world-stats>div>span:last-child{display:flex;flex-direction:column;gap:2px}.stat-icon{display:grid;place-items:center;width:30px;height:30px;border-radius:10px;background:#fff2c8;color:#dda949;font-size:17px}.leaf-icon{background:#e3f4df;color:#83ba88}.world-stats b{font:500 9px 'DM Mono',monospace;color:#456a56;letter-spacing:.35px}.world-stats small{font-size:9px;color:#8da094}.primary-button{display:flex;align-items:center;justify-content:space-between;width:100%;height:46px;padding:0 16px;border-radius:11px;background:#71b886;color:#fff;font-size:13px;font-weight:800;box-shadow:0 7px 15px rgba(102,174,123,.25);transition:transform .2s,background .2s}.primary-button:hover{transform:translateY(-2px);background:#61a978}.button-arrow{font-size:19px;font-weight:500}.panel-hint{margin-top:16px;display:flex;gap:4px;align-items:center;color:#8a9b8e;font-size:10px}.panel-hint span{margin-left:4px}kbd{font:500 9px 'DM Mono',monospace;color:#617d6c;background:#eef5e9;border:1px solid #dfeadd;border-bottom-width:2px;border-radius:4px;padding:3px 5px}.right-rail{position:absolute;z-index:3;right:38px;top:98px;display:flex;flex-direction:column;align-items:center;gap:10px}.weather-card{padding:9px 13px;display:flex;align-items:center;gap:9px;min-width:100px;border-radius:13px}.weather-sun{font-size:23px;color:#ebb95f}.weather-card span:last-child{display:flex;flex-direction:column}.weather-card b{font-size:15px;line-height:16px}.weather-card small{font-size:9px;color:#8b9b8e}.rail-button{height:37px;width:37px;font-size:18px;color:#648474}.bottom-hud{position:absolute;z-index:4;bottom:23px;left:50%;transform:translateX(-50%);display:flex;align-items:center;flex-direction:column;gap:8px;transition:opacity .2s}.quick-hint{font:500 8px 'DM Mono',monospace;color:#5e7869;letter-spacing:.7px;padding:7px 12px;border-radius:20px;background:rgba(255,255,247,.66);backdrop-filter:blur(9px);white-space:nowrap}.quick-hint kbd{font-size:8px;background:rgba(255,255,255,.76);padding:2px 4px}.quick-hint>span{padding:0 5px;color:#a6b5a8}.hotbar-wrap{display:flex;align-items:center;gap:8px}.tool-slot,.inventory-button,.hotbar{height:61px;background:rgba(246,250,239,.86);border:1px solid rgba(255,255,255,.9);box-shadow:0 7px 25px rgba(48,79,56,.14);backdrop-filter:blur(15px);border-radius:12px}.tool-slot{width:52px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;color:#7eb98b}.tool-slot>span{font-size:22px}.tool-slot small,.inventory-button small{font:500 7px 'DM Mono',monospace;letter-spacing:.6px;color:#82948a}.hotbar{display:flex;padding:5px;gap:4px}.slot{position:relative;width:49px;height:49px;border:1px solid transparent;border-radius:8px;display:grid;place-items:center;background:rgba(235,242,229,.7);transition:.15s;cursor:pointer}.slot:hover{background:#f9fff5}.slot.selected{border:2px solid #77bc8b;background:#f9fff5;box-shadow:0 0 0 2px rgba(119,188,139,.14)}.slot .block-icon{width:24px;height:24px;image-rendering:pixelated;filter:drop-shadow(2px 3px 0 rgba(63,80,54,.2))}.slot .slot-key{position:absolute;top:3px;left:5px;color:#8da091;font:8px 'DM Mono',monospace}.slot .count{position:absolute;right:4px;bottom:2px;color:#56705e;font:9px 'DM Mono',monospace;text-shadow:0 1px white}.inventory-button{width:71px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;color:#789684}.inventory-button>span{font-size:18px}.inventory-button small{font-size:6px;white-space:nowrap}.inventory-button kbd{padding:1px 3px;font-size:7px}.corner-note{position:absolute;right:31px;bottom:27px;color:rgba(55,91,69,.65);font:9px 'DM Mono',monospace;letter-spacing:.3px;z-index:3}.corner-note span{color:#e5b553;font-size:12px;margin-right:3px}.overlay,.modal-overlay{position:absolute;inset:0;z-index:9;display:grid;place-items:center;background:rgba(81,137,123,.13);backdrop-filter:blur(3px);transition:opacity .3s,visibility .3s}.overlay.hidden,.modal-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-card{width:min(410px,calc(100vw - 32px));padding:34px 42px 25px;text-align:center;border-radius:22px;background:rgba(255,255,247,.91)}.start-logo{display:flex;justify-content:center;margin-bottom:16px}.brand-mark.big{width:38px;height:38px;gap:3px}.start-card .panel-kicker{margin-bottom:11px}.start-card h2{font-size:34px}.start-card>p{margin:12px 0 19px}.start-controls{display:flex;justify-content:center;gap:15px;margin-top:18px;color:#6b8574;font:8px 'DM Mono',monospace;letter-spacing:.3px}.start-controls span{display:flex;align-items:center;gap:5px}.start-controls small{font-size:7px;color:#98a89b}.back-link{margin-top:16px;background:none;color:#92a399;font-size:11px}.back-link:hover{color:#4d765d}.modal-overlay{z-index:10;background:rgba(35,65,58,.3)}.help-card{width:min(380px,calc(100vw - 30px));padding:30px 34px;border-radius:20px;position:relative}.close-button{position:absolute;right:15px;top:10px;background:none;font-size:27px;color:#87a092}.help-card h2{margin:0 0 18px;font-size:27px;letter-spacing:-.7px}.control-list{display:grid;gap:9px}.control-list div{display:flex;align-items:center;gap:14px}.control-list kbd{min-width:90px;text-align:center}.control-list span{font-size:12px;color:#73877a}.help-foot{margin:19px 0 0;padding-top:14px;border-top:1px solid var(--line);font-size:11px;line-height:1.5;color:#809186}.toast{position:absolute;z-index:8;top:88px;left:50%;transform:translate(-50%,-10px);padding:9px 15px;background:rgba(255,255,247,.9);border-radius:9px;box-shadow:var(--shadow);color:#55745d;font-size:11px;opacity:0;pointer-events:none;transition:.2s}.toast.show{opacity:1;transform:translate(-50%,0)}#crosshair{display:none;position:absolute;z-index:3;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);pointer-events:none}#crosshair i{position:absolute;background:rgba(255,255,255,.93);box-shadow:0 1px 3px #385346;width:2px;height:7px;left:8px}#crosshair i:first-child{top:0}#crosshair i:last-child{top:11px}.target-label{display:none;position:absolute;top:calc(50% + 17px);left:50%;transform:translateX(-50%);font:9px 'DM Mono',monospace;color:white;text-shadow:0 1px 3px #30473d}.playing #crosshair,.playing .target-label{display:block}.playing .left-panel,.playing .right-rail,.playing .corner-note,.playing .world-label,.playing .sound-toggle{opacity:0;pointer-events:none}.playing #bottom-hud{opacity:1}.mobile-controls{display:none}.inventory-panel{position:absolute;z-index:6;left:50%;top:50%;transform:translate(-50%,-50%);width:min(410px,calc(100vw - 28px));padding:21px;border-radius:17px;background:rgba(255,255,248,.95);box-shadow:var(--shadow);border:1px solid white}.inventory-panel h3{margin:0 0 13px;font-size:17px}.inventory-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:7px}.inventory-grid .slot{width:auto;height:56px}.inventory-note{font-size:10px;color:#849487;margin:12px 0 0}
@media(max-width:700px){.topbar{height:59px;padding:0 17px}.world-label{font-size:8px;gap:6px}.brand{font-size:12px;gap:8px}.brand-mark{width:21px;height:21px}.sound-toggle{width:34px;height:34px}.left-panel{left:18px;top:48%;width:275px;padding:23px 22px 18px}.left-panel h1{font-size:30px}.right-rail{right:15px;top:76px}.weather-card{min-width:0;padding:7px 9px}.weather-sun{font-size:20px}.weather-card b{font-size:13px}.weather-card small{font-size:8px}.rail-button{display:none}.bottom-hud{bottom:max(15px,env(safe-area-inset-bottom));width:100%;gap:7px}.quick-hint{display:none}.hotbar-wrap{gap:5px;max-width:100%}.tool-slot{display:none}.hotbar{height:54px;padding:4px;gap:2px}.slot{width:min(46px,11vw);height:44px}.slot .block-icon{width:21px;height:21px}.inventory-button{height:54px;width:57px}.inventory-button small{font-size:5px}.corner-note{display:none}.start-card{padding:27px 26px 19px}.start-card h2{font-size:31px}.start-controls{gap:10px}.start-controls small{display:none}.playing .bottom-hud{bottom:calc(142px + env(safe-area-inset-bottom))}.mobile-controls{display:none;position:absolute;z-index:5;inset:0;pointer-events:none}.playing .mobile-controls{display:block}.move-pad{position:absolute;left:19px;bottom:calc(22px + env(safe-area-inset-bottom));pointer-events:auto;display:flex;flex-direction:column;align-items:center;gap:4px}.move-pad div{display:flex;gap:4px}.move-pad button,.action-pad button{height:43px;min-width:43px;border-radius:12px;background:rgba(255,255,247,.7);border:1px solid rgba(255,255,255,.85);color:#4e7760;box-shadow:0 4px 12px rgba(32,74,58,.12);font-size:14px;touch-action:none;backdrop-filter:blur(8px)}.action-pad{position:absolute;right:17px;bottom:calc(25px + env(safe-area-inset-bottom));display:flex;flex-direction:column;gap:6px;pointer-events:auto}.action-pad button{font:500 8px 'DM Mono',monospace;letter-spacing:.4px;width:52px;min-width:52px;height:37px}.action-pad #mobile-mine{background:rgba(124,186,134,.8);color:white}.look-zone{position:absolute;inset:70px 0 150px 35%;pointer-events:auto;touch-action:none}.playing .left-panel{display:none}}
@media(max-height:560px) and (min-width:701px){.left-panel{top:52%;padding:20px 24px}.left-panel h1{font-size:29px}.world-stats{padding:8px 0;margin-bottom:11px}.left-panel>p{margin:8px 0 14px}.bottom-hud{bottom:9px}.quick-hint{display:none}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas = document.querySelector('#game-canvas');
const shell = document.querySelector('#game-shell');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a9e3ed');
scene.fog = new THREE.Fog('#b9e8dc', 25, 68);
const camera = new THREE.PerspectiveCamera(72, innerWidth / innerHeight, 0.1, 100);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.13;

scene.add(new THREE.HemisphereLight(0xe4faff, 0x75915b, 2.25));
const sun = new THREE.DirectionalLight(0xfff1cc, 2.6);
sun.position.set(-18, 30, 12);
sun.castShadow = false;
scene.add(sun);
const fill = new THREE.DirectionalLight(0xbde7ff, 0.55);
fill.position.set(12, 8, -20); scene.add(fill);

const BLOCKS = [
  { id: 'grass', name: 'Grass block', label: 'GRASS', color: '#78b956', top: '#88c85d', side: '#795b3b' },
  { id: 'dirt', name: 'Dirt', label: 'DIRT', color: '#946a45' },
  { id: 'stone', name: 'Stone', label: 'STONE', color: '#929b9b' },
  { id: 'wood', name: 'Oak wood', label: 'WOOD', color: '#a97b46', top: '#c69a5e' },
  { id: 'leaves', name: 'Leaves', label: 'LEAVES', color: '#579b56' },
  { id: 'sand', name: 'Sand', label: 'SAND', color: '#dfca83' },
];
const inventory = { grass: 12, dirt: 12, stone: 8, wood: 8, leaves: 8, sand: 8 };
let selected = 0;
const world = new Map();
const renderGroups = [];
const blockGeometry = new THREE.BoxGeometry(1, 1, 1);
const tempObject = new THREE.Object3D();
const coordKey = (x,y,z) => `${x},${y},${z}`;
const terrainHeight = (x,z) => {
  const broad = Math.sin(x * .24) * 1.05 + Math.cos(z * .21) * .92 + Math.sin((x + z) * .15) * .62 + Math.cos((x - z) * .12) * .42;
  const rounded = Math.round(broad);
  return Math.max(-1, Math.min(5, rounded));
};
function hash(x, z) { let n = (x * 374761393 + z * 668265263) | 0; n = Math.imul(n ^ (n >>> 13), 1274126177); return ((n ^ (n >>> 16)) >>> 0) / 4294967295; }
function addBlock(x,y,z,type, replace=false) {
  const key = coordKey(x,y,z);
  if (!replace && world.has(key)) return false;
  world.set(key, { x,y,z,type }); return true;
}
function makeWorld() {
  for (let x = -20; x < 20; x++) for (let z = -20; z < 20; z++) {
    let h = terrainHeight(x,z);
    if (Math.abs(x) < 3 && Math.abs(z) < 3) h = 2;
    for (let y = -3; y <= h; y++) {
      let type = y === h ? 'grass' : y >= h - 2 ? 'dirt' : 'stone';
      if ((x*x + z*z > 250 && h <= -1) && y === h) type = 'sand';
      addBlock(x,y,z,type);
    }
  }
  // Little groves, spaced away from the spawn clearing.
  for (let x = -17; x <= 17; x++) for (let z = -17; z <= 17; z++) {
    if (Math.abs(x) < 5 && Math.abs(z) < 5) continue;
    if (hash(x,z) < .967 || Math.abs(x) > 18 || Math.abs(z) > 18) continue;
    const h = Math.abs(x) > 15 || Math.abs(z) > 15 ? terrainHeight(x,z) : terrainHeight(x,z);
    const trunk = 3 + Math.floor(hash(z*9,x*7)*2);
    for (let y = 1; y <= trunk; y++) addBlock(x,h + y,z,'wood');
    const crownY = h + trunk;
    for (let dy = -1; dy <= 2; dy++) {
      const radius = dy === 2 ? 1 : dy === -1 ? 1 : 2;
      for (let dx = -radius; dx <= radius; dx++) for (let dz = -radius; dz <= radius; dz++) {
        if (Math.abs(dx) === radius && Math.abs(dz) === radius && hash(x+dx*3,z+dz*3+dy) < .42) continue;
        if (dx === 0 && dz === 0 && dy < 1) continue;
        addBlock(x+dx,crownY+dy,z+dz,'leaves');
      }
    }
  }
}
function makePixelTexture(base, seed, topGrass=false, sideGrass=false) {
  const c = document.createElement('canvas'); c.width = c.height = 16;
  const ctx = c.getContext('2d');
  ctx.fillStyle = base; ctx.fillRect(0,0,16,16);
  let value = seed * 973;
  for (let i=0;i<60;i++) {
    value = (value * 9301 + 49297) % 233280;
    const shade = value / 233280;
    const x = Math.floor(shade*16); value = (value*9301+49297)%233280;
    const y = Math.floor(value/233280*16);
    ctx.fillStyle = shade > .5 ? 'rgba(255,255,255,.12)' : 'rgba(35,44,31,.13)';
    ctx.fillRect(x,y,1+(i%4===0?1:0),1);
  }
  if (topGrass) {
    ctx.fillStyle = '#7aa957'; ctx.fillRect(0,0,16,16);
    for(let i=0;i<38;i++){const x=Math.floor(Math.random()*16),y=Math.floor(Math.random()*16);ctx.fillStyle=i%2?'#8cc461':'#6da451';ctx.fillRect(x,y,1,1);}
  }
  if (sideGrass) {
    ctx.fillStyle='#779f4c';ctx.fillRect(0,0,16,3);
    ctx.fillStyle='#88b75b';ctx.fillRect(0,3,16,1);
    for(let i=0;i<30;i++){const x=Math.floor(Math.random()*16),y=4+Math.floor(Math.random()*12);ctx.fillStyle=i%2?'rgba(255,255,255,.1)':'rgba(35,30,22,.12)';ctx.fillRect(x,y,1,1);}
  }
  const texture = new THREE.CanvasTexture(c); texture.magFilter=THREE.NearestFilter; texture.minFilter=THREE.NearestFilter; texture.colorSpace=THREE.SRGBColorSpace; return texture;
}
const mats = {};
function makeMaterials() {
  const byId = Object.fromEntries(BLOCKS.map((b,i)=>[b.id,b]));
  for (let i=0;i<BLOCKS.length;i++) {
    const b=BLOCKS[i];
    const sides = makePixelTexture(b.side || b.color, i+2, false, b.id==='grass');
    const top = makePixelTexture(b.top || b.color, i+9, b.id==='grass');
    const sideMat = new THREE.MeshLambertMaterial({map:sides});
    if (b.id==='grass') mats[b.id]=[sideMat,sideMat,new THREE.MeshLambertMaterial({map:top}),sideMat,sideMat,sideMat];
    else if (b.id==='wood') mats[b.id]=[sideMat,sideMat,new THREE.MeshLambertMaterial({map:top}),new THREE.MeshLambertMaterial({map:top}),sideMat,sideMat];
    else mats[b.id]=new THREE.MeshLambertMaterial({map:sides});
  }
}
function rebuildMeshes() {
  for(const old of renderGroups) scene.remove(old);
  renderGroups.length=0;
  for(const b of BLOCKS) {
    const blocks=[...world.values()].filter(v=>v.type===b.id);
    if(!blocks.length) continue;
    const mesh=new THREE.InstancedMesh(blockGeometry,mats[b.id],blocks.length);
    mesh.userData.coords=blocks;
    mesh.frustumCulled=false;
    for(let i=0;i<blocks.length;i++) {
      const p=blocks[i]; tempObject.position.set(p.x,p.y,p.z); tempObject.updateMatrix(); mesh.setMatrixAt(i,tempObject.matrix);
    }
    mesh.instanceMatrix.needsUpdate=true; mesh.computeBoundingSphere(); scene.add(mesh); renderGroups.push(mesh);
  }
  document.querySelector('#blocks-count').textContent=`${world.size.toLocaleString()} blocks`;
}
makeWorld(); makeMaterials(); rebuildMeshes();

// Soft, distant cloud puffs add a little depth without obscuring the horizon.
const cloudMat=new THREE.MeshLambertMaterial({color:0xffffff,transparent:true,opacity:.83});
for(let i=0;i<15;i++) {
  const cloud=new THREE.Group(); const cx=(hash(i,8)-.5)*75, cz=(hash(i+41,9)-.5)*75, cy=15+hash(i,3)*5;
  for(let j=0;j<4;j++){const puff=new THREE.Mesh(new THREE.BoxGeometry(2.8+hash(i,j)*2,.45,1.3),cloudMat);puff.position.set(j*1.6-2.2,hash(j,i)*.28,j%2*.5);cloud.add(puff);}
  cloud.position.set(cx,cy,cz);scene.add(cloud);
}

const highlight=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(1.012,1.012,1.012)),new THREE.LineBasicMaterial({color:0xffffff,transparent:true,opacity:.8}));
highlight.visible=false;scene.add(highlight);
const raycaster=new THREE.Raycaster();raycaster.far=6;
let targetHit=null;
let yaw=Math.PI*.20,pitch=-.12;
const player={x:0,z:0,foot:2.5,vy:0,onGround:true};
const eyeHeight=1.62;
function groundAt(x,z) {
  const bx=Math.round(x),bz=Math.round(z);
  let top=-3.5;
  for(const p of world.values()) if(p.x===bx&&p.z===bz&&p.y+.5>top) top=p.y+.5;
  return top;
}
function updateCamera(){camera.position.set(player.x,player.foot+eyeHeight,player.z);camera.rotation.order='YXZ';camera.rotation.set(pitch,yaw,0);}
updateCamera();
const keys=new Set();let playing=false, inventoryOpen=false, lastTime=performance.now(), soundOn=false, audioCtx=null, toastTimer;
function showToast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1600);}
function startGame(){
  document.querySelector('#start-overlay').classList.add('hidden');
  if(!playing){playing=true;shell.classList.add('playing');showToast('Welcome to your little world ✦');}
  try{canvas.requestPointerLock?.();}catch(e){}
}
function unlock(){if(document.pointerLockElement===canvas)document.exitPointerLock();}
document.querySelector('#play-button').addEventListener('click',startGame);
document.querySelector('#start-button').addEventListener('click',startGame);
document.querySelector('#back-button').addEventListener('click',()=>document.querySelector('#start-overlay').classList.add('hidden'));
canvas.addEventListener('click',()=>{if(playing&&innerWidth>700&&document.pointerLockElement!==canvas)canvas.requestPointerLock?.();});
